package cl.bancoxyz.notification;import java.util.*;import java.util.concurrent.CopyOnWriteArrayList;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Service;@Service public class NotificationStore{private final List<String> events=new CopyOnWriteArrayList<>();@KafkaListener(topics="${bank.events.transaction-topic}",groupId="notification-service") public void onTransaction(String event){events.add(event);if(events.size()>100)events.remove(0);}public List<String> all(){return List.copyOf(events);}}